#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Default values\nSSH_DIR=\"$HOME/.ssh\"\nKEY_TYPE=\"ed25519\"\nBITS=4096\nCOMMENT=\"$(whoami)@$(hostname)\"\n\nprint_usage() {\n  echo "Usage: $0 [--ssh-dir PATH] [--key-type TYPE] [--bits BITS] [--comment COMMENT]"\n  exit 1\n}\n\n# Parse long options\nwhile [[ $# -gt 0 ]]; do\n  case $1 in\n    --ssh-dir)\n      SSH_DIR=\"$2\"; shift 2;;\n    --key-type)\n      KEY_TYPE=\"$2\"; shift 2;;\n    --bits)\n      BITS=\"$2\"; shift 2;;\n    --comment)\n      COMMENT=\"$2\"; shift 2;;\n    -h|--help)\n      print_usage;;\n    *)\n      echo "Unknown option: $1"; print_usage;;\n  esac\n done\n\n# Validate key type\nif [[ \"$KEY_TYPE\" != \"rsa\" && \"$KEY_TYPE\" != \"ed25519\" ]]; then\n  echo "Unsupported key type: $KEY_TYPE"; exit 1;\nfi\n\nTIMESTAMP=$(date +%s)\n\n# Ensure SSH directory exists\nmkdir -p \"$SSH_DIR\"\n\nPRIVATE_KEY=\"$SSH_DIR/id_$KEY_TYPE\"\nPUBLIC_KEY=\"$SSH_DIR/id_$KEY_TYPE.pub\"\n\n# Backup existing keys if they exist\nif [[ -f \"$PRIVATE_KEY\" ]]; then\n  mv \"$PRIVATE_KEY\" \"${PRIVATE_KEY}.bak.$TIMESTAMP\"\nfi\nif [[ -f \"$PUBLIC_KEY\" ]]; then\n  mv \"$PUBLIC_KEY\" \"${PUBLIC_KEY}.bak.$TIMESTAMP\"\nfi\n\n# Prepare ssh-keygen options\nBITS_OPT=\"\"\nif [[ \"$KEY_TYPE\" == \"rsa\" ]]; then\n  BITS_OPT=\"-b $BITS\"\nfi\n\n# Generate new key pair (no passphrase)\nssh-keygen -t \"$KEY_TYPE\" $BITS_OPT -C \"$COMMENT\" -f \"$PRIVATE_KEY\" -N \"\"\n\n# Ensure authorized_keys exists and append the new public key\nAUTHORIZED_KEYS=\"$SSH_DIR/authorized_keys\"\ntouch \"$AUTHORIZED_KEYS\"\ncat \"$PUBLIC_KEY\" >> \"$AUTHORIZED_KEYS\"\n\necho "SSH key rotation complete. New key stored at $PRIVATE_KEY"\n
